function GLMC-BRUTE-FORCE(E, V):
    best_val <- +inf;  best_cut <- none
    for r = 1 to |V| - 1:                      # proper cuts only
        for each A subset of V with |A| = r:
            labels <- { l : (u,v,l) in E and (u in A) != (v in A) }
            val <- |labels|
            if val < best_val:
                best_val <- val;  best_cut <- A
                if val == 0: return (0, A)      # sound early exit
    if best_val == +inf: return (0, none)       # |V| <= 1
    return (best_val, best_cut)
